import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as s,af as r}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const k=JSON.parse('{"title":"How to write prompts","description":"Write prompts for coding assistants and in-product models. Mechanisms live on Learn LLM chapter 15. This page is practice.","frontmatter":{"listed":false,"title":"How to write prompts","description":"Write prompts for coding assistants and in-product models. Mechanisms live on Learn LLM chapter 15. This page is practice.","outline":[2,3],"pageClass":"catalog-page","prev":false,"next":{"text":"Be clear · Claude official","link":"/tech/prompt/claude-prompt-best-practices"},"domain":"tech","tags":["prompt"],"navOrder":1,"llm":[15]},"headers":[],"relativePath":"tech/prompt/index.md","filePath":"tech/prompt/index.md","lastUpdated":1788250975000}'),o={name:"tech/prompt/index.md"};function n(i,t,p,l,d,h){return s(),a("div",null,[...t[0]||(t[0]=[r(`<h1 id="how-to-write-prompts" tabindex="-1">How to write prompts <a class="header-anchor" href="#how-to-write-prompts" aria-label="Permalink to &quot;How to write prompts&quot;">​</a></h1><p><strong>Bottom line:</strong> a vague prompt stays vague on a better model. Write the <strong>task, constraints, output, and examples</strong> first. Then XML / JSON / agents.</p><p>Why the tactics work (four-part system prompt, few-shot following the example, three JSON tiers, memory modes) lives on Learn LLM <a href="https://llm.zenheart.site/chapters/15-prompt-memory" target="_blank" rel="noreferrer">chapter 15</a>. This site only teaches <strong>how to write, which tool to put it in, and how to check it in the repo</strong>.</p><h2 id="audience-and-non-goals" tabindex="-1">Audience and non-goals <a class="header-anchor" href="#audience-and-non-goals" aria-label="Permalink to &quot;Audience and non-goals&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>For</strong></td><td>Engineers who already open Cursor / Claude Code / Copilot, or who will call a model from a product</td></tr><tr><td><strong>Prerequisites</strong></td><td><a href="/tech/fundamentals/LLM.html">LLM basics</a> and the <a href="/tech/fundamentals/context.html">context window</a></td></tr><tr><td><strong>You will be able to</strong></td><td>Turn &quot;please fix this&quot; into an executable task; send product output through a schema; land an <code>AGENTS.md</code> the assistant will run</td></tr><tr><td><strong>Not this page</strong></td><td>Product click-paths → <a href="/products/">Products</a>. Attention / training / memory implementations → Learn LLM. Multi-tool loops → <a href="/tech/patterns/agent/">Agents</a></td></tr></tbody></table><h2 id="one-concept-table" tabindex="-1">One concept table <a class="header-anchor" href="#one-concept-table" aria-label="Permalink to &quot;One concept table&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Remember</th><th>In engineering</th><th>Why (Learn LLM)</th></tr></thead><tbody><tr><td>Standing rules in system / developer; this turn&#39;s data in user</td><td>Do not mix today&#39;s ticket with &quot;how we always classify&quot;</td><td><a href="https://llm.zenheart.site/chapters/15-prompt-memory" target="_blank" rel="noreferrer">Ch.15 A1</a></td></tr><tr><td>Examples must match the instructed format</td><td>JSON in the rules + prose examples → the model copies prose</td><td><a href="https://llm.zenheart.site/chapters/15-prompt-memory" target="_blank" rel="noreferrer">Ch.15 A2</a></td></tr><tr><td>JSON that must parse goes through the API schema</td><td>Do not rely on &quot;please return valid JSON&quot;</td><td><a href="https://llm.zenheart.site/chapters/15-prompt-memory" target="_blank" rel="noreferrer">Ch.15 A3</a></td></tr><tr><td>Production prompts live in code</td><td>Types, review, regression</td><td><a href="https://llm.zenheart.site/chapters/15-prompt-memory" target="_blank" rel="noreferrer">Ch.15 A4</a></td></tr><tr><td>Over-window history must be trimmed on purpose</td><td>Naive slices break tool pairings</td><td><a href="https://llm.zenheart.site/chapters/15-prompt-memory" target="_blank" rel="noreferrer">Ch.15 A5</a></td></tr></tbody></table><h2 id="how-to-read-this-section" tabindex="-1">How to read this section <a class="header-anchor" href="#how-to-read-this-section" aria-label="Permalink to &quot;How to read this section&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>This page (20 minutes: assistant first, then product)</span></span>
<span class="line"><span>  → 1. Claude official              XML / few-shot</span></span>
<span class="line"><span>  → 2. AGENTS.md                    one contract per repo</span></span>
<span class="line"><span>  → 3. Agent engineering            when the assistant must act</span></span>
<span class="line"><span>  → Appendix                        other products&#39; system prompts</span></span></code></pre></div><table tabindex="0"><thead><tr><th>You are stuck on</th><th>Read</th></tr></thead><tbody><tr><td>Still typing &quot;please fix this&quot;</td><td><strong>Finish the assistant section below</strong></td></tr><tr><td>Official XML examples</td><td><a href="/tech/prompt/claude-prompt-best-practices.html">Be clear · Claude official</a></td></tr><tr><td>Every assistant guesses the package manager</td><td><a href="/tech/prompt/agents-doc.html">AGENTS.md</a></td></tr><tr><td>Product output must survive <code>JSON.parse</code></td><td><a href="/zh/tech/prompt/json-prompt-best-practices.html">ZH JSON note</a> (schema how-to)</td></tr><tr><td>Compare vendor system prompts</td><td><a href="/tech/prompt/system-prompts-collection.html">Appendix · System prompts</a></td></tr></tbody></table><h2 id="coding-assistant-a-prompt-you-can-send-today" tabindex="-1">Coding assistant: a prompt you can send today <a class="header-anchor" href="#coding-assistant-a-prompt-you-can-send-today" aria-label="Permalink to &quot;Coding assistant: a prompt you can send today&quot;">​</a></h2><p>Do not send:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>please fix the settings page</span></span></code></pre></div><p>Send:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Task: fix the Save button on Settings in dark mode (white-on-white, clickable, invisible).</span></span>
<span class="line"><span>Files: read src/pages/Settings.vue first. Touch only this file and the tokens it uses.</span></span>
<span class="line"><span>Constraints: do not change light mode; do not add a CSS framework.</span></span>
<span class="line"><span>Done when: the button is readable in dark theme; pnpm test stays green.</span></span>
<span class="line"><span>Do not: rewrite Settings.</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Tool</th><th>Where the prompt lives</th><th>Product page</th></tr></thead><tbody><tr><td>Cursor</td><td>This chat / agent; repeating rules in <code>.cursor/rules</code> or root <code>AGENTS.md</code></td><td><a href="/products/cursor/">Cursor</a></td></tr><tr><td>Claude Code</td><td>This chat; repo rules in <code>CLAUDE.md</code> + <code>AGENTS.md</code></td><td><a href="/products/claude/claude-code.html">Claude Code</a></td></tr><tr><td>Codex / Copilot Agent</td><td>This chat; cross-tool minimum is <code>AGENTS.md</code></td><td><a href="/products/codex/">Codex</a> · <a href="/products/copilot/">Copilot</a></td></tr></tbody></table><p>The current task stays in the chat. <code>AGENTS.md</code> only holds rules that are always true for the repo.</p><h2 id="in-product-model-the-prompt-is-code" tabindex="-1">In-product model: the prompt is code <a class="header-anchor" href="#in-product-model-the-prompt-is-code" aria-label="Permalink to &quot;In-product model: the prompt is code&quot;">​</a></h2><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> system</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> \`# Identity</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">You turn user feedback into a ticket a duty engineer can file.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"># Instructions</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">- Use only the user&#39;s words. Do not invent repro steps.</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">- If repro is missing, nextAction must start with &quot;Ask the user for:&quot;.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"># Examples</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;example&gt;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;input&gt;Forgot-password on login does nothing. Chrome 128.&lt;/input&gt;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;output&gt;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">{&quot;severity&quot;:&quot;high&quot;,&quot;area&quot;:&quot;auth&quot;,&quot;summary&quot;:&quot;Forgot-password does not respond (Chrome 128)&quot;,&quot;nextAction&quot;:&quot;Ask the user for: console error after the click&quot;}</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;/output&gt;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;/example&gt;\`</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> user</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> \`&lt;input&gt;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">feedback</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;/input&gt;\`</span></span></code></pre></div><p>Keep <code>system</code> in a <code>buildTicketPrompt()</code> next to the feature. OpenAI is shutting down reusable prompt objects (<code>v1/prompts</code>, planned 2026-11-30). Do not treat the vendor console as the source of truth. For parseable JSON use a schema (see the <a href="/zh/tech/prompt/json-prompt-best-practices.html">ZH JSON note</a>).</p><h2 id="practice-in-this-repo" tabindex="-1">Practice in this repo <a class="header-anchor" href="#practice-in-this-repo" aria-label="Permalink to &quot;Practice in this repo&quot;">​</a></h2><p>Open the root <code>AGENTS.md</code> / <code>Claude.md</code>: <code>pnpm</code> only at the root, docs in Chinese, commit messages in English, <code>pnpm docs:build</code> before commit. That is the smallest landed prompt, not another theory page.</p><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><ul><li>Eating the paper catalog (CoT / ToT) before the task is clear.</li><li>Only writing bans.</li><li>Nailing JSON with English instead of a schema.</li><li>Reading leaked system prompts as a course.</li><li>Rewriting everything on a model bump — usually you only retune initiative, verbosity, and stop conditions.</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ol><li><a href="https://github.com/anthropics/prompt-eng-interactive-tutorial" target="_blank" rel="noreferrer">Anthropic Interactive Tutorial</a></li><li><a href="/tech/prompt/claude-prompt-best-practices.html">Claude official</a> → <a href="/tech/prompt/agents-doc.html">AGENTS.md</a></li><li>Wire a model from <a href="/integration/apis/">Integrate</a></li></ol><h2 id="go-deeper" tabindex="-1">Go deeper <a class="header-anchor" href="#go-deeper" aria-label="Permalink to &quot;Go deeper&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Kind</th><th>Resource</th></tr></thead><tbody><tr><td>Mechanisms</td><td>Learn LLM <a href="https://llm.zenheart.site/chapters/15-prompt-memory" target="_blank" rel="noreferrer">chapter 15</a></td></tr><tr><td>Official</td><td><a href="https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices" target="_blank" rel="noreferrer">Anthropic</a> · <a href="https://developers.openai.com/api/docs/guides/prompt-engineering" target="_blank" rel="noreferrer">OpenAI</a> · <a href="https://ai.google.dev/gemini-api/docs/prompting-strategies" target="_blank" rel="noreferrer">Gemini</a> · <a href="https://agents.md/" target="_blank" rel="noreferrer">AGENTS.md</a> · <a href="https://developers.openai.com/api/docs/guides/structured-outputs" target="_blank" rel="noreferrer">Structured Outputs</a></td></tr><tr><td>Practice</td><td><a href="https://github.com/anthropics/prompt-eng-interactive-tutorial" target="_blank" rel="noreferrer">Anthropic Interactive Tutorial</a> · <a href="https://developers.openai.com/cookbook" target="_blank" rel="noreferrer">Cookbook</a></td></tr><tr><td>Notes</td><td><a href="https://github.com/brexhq/prompt-engineering" target="_blank" rel="noreferrer">brexhq/prompt-engineering</a></td></tr></tbody></table><p>Skip <a href="https://github.com/f/prompts.chat" target="_blank" rel="noreferrer">Awesome ChatGPT Prompts</a> as a first lesson.</p>`,29)])])}const b=e(o,[["render",n]]);export{k as __pageData,b as default};
